CREATE TYPE "DeviceStatus" AS ENUM ('PENDING','ONLINE','OFFLINE','BLOCKED');CREATE TYPE "SyncJobStatus" AS ENUM ('RECEIVED','APPLIED','REJECTED','CONFLICT');
CREATE TABLE "Device"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"branchId" UUID NOT NULL REFERENCES "Branch"("id") ON DELETE RESTRICT,"merchantId" UUID REFERENCES "MerchantAccount"("id") ON DELETE SET NULL,"name" VARCHAR(120) NOT NULL,"deviceType" VARCHAR(60) NOT NULL,"platform" VARCHAR(40) NOT NULL,"osVersion" VARCHAR(60),"appVersion" VARCHAR(40),"publicKey" TEXT,"status" "DeviceStatus" NOT NULL DEFAULT 'PENDING',"lastSeenAt" TIMESTAMPTZ,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE "Ticket" ADD CONSTRAINT "Ticket_deviceId_fkey" FOREIGN KEY("deviceId") REFERENCES "Device"("id") ON DELETE SET NULL;
CREATE TABLE "SyncJob"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"deviceId" UUID NOT NULL REFERENCES "Device"("id") ON DELETE RESTRICT,"clientMutationId" VARCHAR(100) NOT NULL,"operation" VARCHAR(80) NOT NULL,"requestHash" CHAR(64) NOT NULL,"status" "SyncJobStatus" NOT NULL DEFAULT 'RECEIVED',"serverEntityId" UUID,"response" JSONB,"errorCode" VARCHAR(100),"receivedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"completedAt" TIMESTAMPTZ,UNIQUE("tenantId","deviceId","clientMutationId"));
CREATE INDEX "device_tenant_status_seen" ON "Device"("tenantId","status","lastSeenAt");CREATE INDEX "sync_tenant_status_time" ON "SyncJob"("tenantId","status","receivedAt");
ALTER TABLE "Device" ENABLE ROW LEVEL SECURITY;ALTER TABLE "SyncJob" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_device_isolation ON "Device" USING("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_sync_isolation ON "SyncJob" USING("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
